import{z as s,x as B,o as A,c as p,q as o,j as i,D as r,d as e,s as t,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"LISA","description":"","frontmatter":{"title":"LISA","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lisa-layerwise.md","filePath":"llm/lisa-layerwise.md","lastUpdated":1791063341000}'),d={name:"llm/lisa-layerwise.md"};function m(D,a,S,L,u,F){const E=B("Mermaid");return A(),p("div",null,[a[2]||(a[2]=o('<h1 id="lisa" tabindex="-1">LISA <a class="header-anchor" href="#lisa" aria-label="Permalink to &quot;LISA&quot;">​</a></h1><div class="epigraph"><p>同一时刻不必训所有层：按重要性抽样解冻一层或几层，显存接近只训切片，而长期仍能扫过整网。</p><footer>—— Pan 等，LISA: Layerwise Importance Sampling for Memory-Efficient Large Language Model Fine-Tuning，2024</footer></div><p><a href="/llm/galore">GaLore</a> 在层内压缩优化器状态，所有层仍同时活着。再省一步是<strong>层间时间分片</strong>：大多数层冻结，只有被抽中的层收梯度。Pan、Liu、Diao 等人的 LISA（Layerwise Importance Sampling）按层重要性抽样解冻，而不是永远只训最后几层。缺口：固定「只训顶层」会让底层领域特征不动；同时训所有层又回到全参显存。本课写层抽样，不把 ReLoRA 的秩累积提前讲完。名勿与医学影像 LISA 或其它缩写混淆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全参 SFT 的激活与梯度随深度线性涨（再加检查点策略）。经验上指令梯度在上层更强，但底层仍承担格式无关的特征。永远冻底层，等于线性探针加顶层微调，领域词与长程特征改不到。<a href="/llm/domain-adaptation-ft">领域 DAPT</a> 尤其吃亏。永远全解冻，显存打满。</p><p>需要一种日程：步 \\(t\\) 只让集合 \\(S_t\\) 里的层可训练，\\(S_t\\) 随时间覆盖全体，且更重要的层被抽得更勤。重要性若用均匀，退化成随机层切换；若用启发式（梯度范数、层对损失的贡献），预算集中在真在干活的层。</p><h3 id="不是-dropout-层、也不是-pipeline-切段" tabindex="-1">不是 Dropout 层、也不是 Pipeline 切段 <a class="header-anchor" href="#不是-dropout-层、也不是-pipeline-切段" aria-label="Permalink to &quot;不是 Dropout 层、也不是 Pipeline 切段&quot;">​</a></h3><p>Dropout 是前向随机切激活。流水线并行是空间切层到不同卡，每层仍可能在算梯度。LISA 是优化器意义上的冻结：未选中层 <code>requires_grad=False</code>，不为其存 Adam。前向仍过全网，以提供正确的条件。</p><p><span class="marginnote">论文报告在指令微调设定下，记忆显著低于全参，质量接近。主张依赖「不是所有层每步都需要更新」——与 LoRA 的低秩假设并列，是另一条稀疏性：层稀疏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为每层维护重要性分数（如近期梯度范数的滑动平均）。每 \\(K\\) 步按分数做有放回或无放回抽样，解冻 \\(k\\) 层（常 \\(k=1\\) 或少数），其余冻结。学习率按全参 SFT（<a href="/llm/lora-vs-full-lr">η 分叉</a>），因为被解冻的权重是 \\(W\\) 本身，不是 \\(BA\\)。可与 <a href="/llm/lora">LoRA</a> 结合：只在抽中的层上挂适配器——那就变成「层抽样的 LoRA」，配方必须写清。</p><p><span class="marginnote">重要性抽样就是「越重要的越常被抽到」：给每层打一个分（比如最近梯度有多大），抽层时分数高的层中签概率更高，而不是掷均匀骰子。直觉类比：复习时间有限，优先翻错题多的章节，但偶尔也要翻其他章，防止整本书的知识掉光。</span></p><p>SFT 契约不变：<a href="/llm/response-only-loss">仅回复</a>、<a href="/llm/chat-template">模板</a>。抽样周期 \\(K\\) 过短，层切换像噪声；过长，等于阶段性只训固定切片，与「只训顶层」无异。</p>',13)),(A(),i(n,null,{default:r(()=>[t(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E5%B1%82%E9%87%8D%E8%A6%81%E6%80%A7%E5%88%86%E6%95%B0%22%5D%20--%3E%20S%5B%22%E6%8A%BD%E6%A0%B7%E8%A7%A3%E5%86%BB%20k%20%E5%B1%82%22%5D%0A%20%20S%20--%3E%20F%5B%22%E5%85%B6%E4%BD%99%E5%B1%82%E5%86%BB%E7%BB%93%EF%BC%8C%E6%97%A0%20Adam%22%5D%0A%20%20F%20--%3E%20U%5B%22%E5%89%8D%E5%90%91%E4%BB%8D%E8%BF%87%E5%85%A8%E7%BD%91%22%5D%0A%20%20U%20--%3E%20I%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"实现：冻结层仍参与前向，激活显存未必等比例下降，除非配合检查点只存可训练层附近。LISA 的主省头是优化器状态与可训练层的梯度。声称「显存 ÷ 层数」前要测激活。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,[e("长期看，权重更新的时间积分可以覆盖所有层，近似全参轨迹的稀疏采样版。短期看，每步是一个极深网络上的浅更新。Adam 的动量在层被冻期间如何处理（清零、冻结保存、还是层切换就丢）会影响稳定性：保存每人一份动量就回到接近全量优化器状态，省不下记忆；丢弃则每层每次被抽中都像冷启动。工程上常为"),l("strong",null,"当前解冻层"),e("才分配 Adam，接受动量间断——这是偏差来源。")],-1)),(A(),i(n,null,{default:r(()=>[t(E,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FULL%5B%22%E5%85%A8%E5%8F%82%20SFT%EF%BC%9A%E6%89%80%E6%9C%89%E5%B1%82%E8%A7%A3%E5%86%BB%22%5D%20--%3E%20A1%5B%22%E6%AF%8F%E5%B1%82%E9%83%BD%E5%AD%98%E6%A2%AF%E5%BA%A6%20%2B%20Adam%20m%2Fv%22%5D%0A%20%20LISA%5B%22LISA%EF%BC%9A%E6%AF%8F%E6%AD%A5%E5%8F%AA%E8%A7%A3%E5%86%BB%20k%20%E5%B1%82%22%5D%20--%3E%20A2%5B%22%E4%BB%85%E6%8A%BD%E4%B8%AD%E5%B1%82%E7%9A%84%E6%A2%AF%E5%BA%A6%20%2B%20Adam%22%5D%0A%20%20LORA%5B%22LoRA%EF%BC%9A%E5%85%A8%E7%BD%91%E5%86%BB%E7%BB%93%22%5D%20--%3E%20A3%5B%22%E5%8F%AA%E8%AE%AD%E4%BD%8E%E7%A7%A9%20BA%20%E5%A2%9E%E9%87%8F%22%5D%0A%20%20A1%20--%3E%20B1%5B%22%E6%98%BE%E5%AD%98%E6%9C%80%E9%87%8D%22%5D%0A%20%20A2%20--%3E%20B2%5B%22%E7%9C%81%E4%BC%98%E5%8C%96%E5%99%A8%E4%B8%8E%E6%A2%AF%E5%BA%A6%E5%A4%A7%E5%A4%B4%EF%BC%8C%E5%89%8D%E5%90%91%E6%BF%80%E6%B4%BB%E4%B8%8D%E5%8F%98%22%5D%0A%20%20A3%20--%3E%20B3%5B%22%E6%98%BE%E5%AD%98%E6%9C%80%E5%B0%8F%EF%BC%8C%E4%BD%86%E5%8F%AA%E8%B0%83%E4%BD%8E%E7%A7%A9%E5%AD%90%E7%A9%BA%E9%97%B4%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">数字实例：7B 模型做全参 SFT，Adam 的一阶动量加二阶矩按 FP32 各存一份就是 \\(7\\times10^9\\times8\\approx56\\) GB，再加一份可训练参数的梯度。LISA 只解冻 32 层中的 1 层时，这部分大约除以 32，掉到约 2 GB——省的正是这个大头；激活显存不受影响，因为前向仍要过所有层。</span></p><p>重要性抽样把预算给梯度大的层。指令 SFT 上往往偏向上层，底层更新稀。若任务其实要改嵌入与底层（新特殊 token、领域词），应给底层设抽样下限，避免被分数饿死。</p><p><span class="marginnote">GaLore 与 LISA 可叠：抽中的层再对梯度做低秩投影。复杂度上升，只在显存极端时才值得同时开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>预训练从随机初始化需要所有层密集更新，LISA 不适合当主预训练算法。短 SFT、数据少时，层切换引入的噪声可能大于收益，不如 LoRA。多卡同步：各 rank 必须抽同一组层，否则梯度对不齐。评测仍要通用能力：若抽样长期忽略底层，遗忘模式会像「顶层过拟合」。</p><p><span class="marginnote">常见误区：初学者容易以为「冻结层」会把前向计算也跳过，以为 LISA 还能省前向时间。实际上冻结只是 <code>requires_grad=False</code>：前向照常算完所有层，省的是反向梯度和 Adam 状态的存储；前向的速度与激活显存基本不变，除非再配合梯度检查点。</span></p><p>下一课 ReLoRA 用时间累积<strong>秩</strong>；LISA 用时间累积<strong>层覆盖</strong>。二者都是时间换容量，对象不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LISA 按重要性抽样解冻少数层，降低优化器与梯度显存。</li><li>前向仍过全网；未解冻层无 Adam。</li><li>学习率按全参；底层可设抽样下限以免饿死。</li><li>动量在层切换时通常不保留，是偏差来源。</li><li>不适合需要全层密集更新的预训练。</li><li>出处：Pan 等，LISA: Layerwise Importance Sampling for Memory-Efficient LLM Fine-Tuning，2024。</li></ul>',9))])}const c=s(d,[["render",m]]);export{h as __pageData,c as default};
